def find(iclass, iform=None, encoding=None, vl=None, mem=False):
    """Exactly one entry or KeyError. mem=False selects register forms, mem=True memory forms."""
    out = [e for e in ENTRIES if e["key"]["iclass"] == iclass
           and (iform is None or e["key"]["iform"] == iform)
           and (encoding is None or e["encoding"] == encoding)
           and (vl is None or e["vl"] == vl)
           and (iform is not None or any(o["kind"] == "mem" for o in e["operands"]) == mem)]
    if len(out) != 1:
        raise KeyError("%s %s %s %s mem=%s -> %d entries" % (iclass, iform, encoding, vl, mem, len(out)))
    return out[0]


def index(with_hash=True):
    b = bundle_hash() if with_hash else None
    rows = []
    for e in ENTRIES:
        d = _decl(e)
        if with_hash:
            d["content_hash"] = content_hash(e, b)
        rows.append(d)
    return {"semantics_bundle": b, "entries": rows}


def nan_role_of(e, role):
    """NaN-order role of one operand; anything not whitelisted is an observer (RULES.md §2)."""
    return e.get("nan_role", {}).get(role, OB)


FAMILIES_FP = sorted({e["family"] for e in ENTRIES if e["fp_sensitive"]})

if __name__ == "__main__":
    idx = index()
    st = {}
    for e in ENTRIES:
        st[e["key"]["iform_status"]] = st.get(e["key"]["iform_status"], 0) + 1
    print(json.dumps({"bundle": idx["semantics_bundle"], "n_entries": len(idx["entries"]),
                      "iform_status": st, "fp_families": FAMILIES_FP}, indent=1))
